static _R _dragByKeyScreenshotMid(String method, Map<String, String> params) async {
  final keyValue = params['key'];
  if (keyValue == null || keyValue.isEmpty) {
    return _error('key parameter required');
  }
  final dx = double.tryParse(params['dx'] ?? '');
  final dy = double.tryParse(params['dy'] ?? '');
  if (dx == null || dy == null) {
    return _error('dx and dy parameters required (double)');
  }
  final steps = (int.tryParse(params['steps'] ?? '12') ?? 12).clamp(1, 200);
  final midStep = (int.tryParse(params['midStep'] ?? '') ?? (steps ~/ 2))
      .clamp(0, steps - 1);
  final pixelRatio = double.tryParse(params['pixelRatio'] ?? '') ?? 1.0;

  final element = _findElementByKey(keyValue);
  if (element == null) {
    return _error('no widget found with key "$keyValue"');
  }

  final isHorizontal = dx.abs() >= dy.abs();
  final delta = Offset(dx / steps, dy / steps);

  // Find the first GestureDetector in subtree that supports the relevant
  // drag callbacks so we can invoke them directly.
  Element? dragEl;
  GestureDetector? dragWidget;
  RenderBox? dragBox;
  _walkSubtree(element, (el) {
    final widget = el.widget;
    if (widget is! GestureDetector) return false;

    final ro = el.findRenderObject();
    if (ro is! RenderBox || !ro.attached || !ro.hasSize || ro.size.isEmpty) {
      return false;
    }

    if (isHorizontal) {
      if (widget.onHorizontalDragStart == null ||
          widget.onHorizontalDragUpdate == null ||
          widget.onHorizontalDragEnd == null) return false;
    } else {
      if (widget.onVerticalDragStart == null ||
          widget.onVerticalDragUpdate == null ||
          widget.onVerticalDragEnd == null) return false;
    }

    dragEl = el;
    dragWidget = widget;
    dragBox = ro;
    return true;
  });

  if (dragEl == null || dragWidget == null || dragBox == null) {
    return _error(
      'found key "$keyValue" but no usable GestureDetector drag callbacks in subtree',
    );
  }

  final startGlobal =
      dragBox!.localToGlobal(dragBox!.size.center(Offset.zero));

  Future<Map<String, Object?>> captureDuring() async {
    final renderObject =
        DebugHooks.screenshotBoundaryKey.currentContext?.findRenderObject();
    if (renderObject is! RenderRepaintBoundary) {
      return {'error': 'screenshot boundary not mounted yet'};
    }
    try {
      final image = await renderObject.toImage(pixelRatio: pixelRatio);
      final png = await image.toByteData(format: ui.ImageByteFormat.png);
      final width = image.width;
      final height = image.height;
      image.dispose();
      if (png == null) {
        return {'error': 'toByteData returned null'};
      }
      return {
        'png_base64': base64Encode(png.buffer.asUint8List()),
        'width': width,
        'height': height,
      };
    } catch (e) {
      return {'error': 'screenshot failed: $e'};
    }
  }

  Map<String, Object?> duringShot = {'error': 'not captured'};

  if (isHorizontal) {
    dragWidget!.onHorizontalDragStart!(
      DragStartDetails(
        globalPosition: startGlobal,
        localPosition: dragBox!.globalToLocal(startGlobal),
      ),
    );
    var p = startGlobal;
    for (var i = 0; i < steps; i++) {
      p += delta;
      dragWidget!.onHorizontalDragUpdate!(
        DragUpdateDetails(
          globalPosition: p,
          localPosition: dragBox!.globalToLocal(p),
          delta: delta,
          primaryDelta: delta.dx,
        ),
      );
      if (i == midStep) {
        await SchedulerBinding.instance.endOfFrame;
        duringShot = await captureDuring();
      }
    }
    dragWidget!.onHorizontalDragEnd!(
      DragEndDetails(primaryVelocity: 0),
    );
  } else {
    dragWidget!.onVerticalDragStart!(
      DragStartDetails(
        globalPosition: startGlobal,
        localPosition: dragBox!.globalToLocal(startGlobal),
      ),
    );
    var p = startGlobal;
    for (var i = 0; i < steps; i++) {
      p += delta;
      dragWidget!.onVerticalDragUpdate!(
        DragUpdateDetails(
          globalPosition: p,
          localPosition: dragBox!.globalToLocal(p),
          delta: delta,
          primaryDelta: delta.dy,
        ),
      );
      if (i == midStep) {
        await SchedulerBinding.instance.endOfFrame;
        duringShot = await captureDuring();
      }
    }
    dragWidget!.onVerticalDragEnd!(
      DragEndDetails(primaryVelocity: 0),
    );
  }

  return _ok({
    'during': duringShot,
    'key': keyValue,
    'dx': dx,
    'dy': dy,
    'steps': steps,
    'midStep': midStep,
  });
}

